_TITHI_INDEX = {n: i for i, n in enumerate(TITHI_NAMES)} | {"Purnima": 14, "Amavasya": 15}


def supported() -> dict:
    return dict(LANGS)


def localize_day(row: dict, lang: str) -> dict:
    """Return the row with *_loc fields and labels for one of the supported languages (unchanged for hi/en/unknown)."""
    if lang not in LANGS:
        return row
    out = dict(row)
    try:
        out["vara_loc"] = VARA_L[lang][row["vara_index"]] if "vara_index" in row else VARA_L[lang][["Ravivara", "Somavara", "Mangalavara", "Budhavara", "Guruvara", "Shukravara", "Shanivara"].index(row["vara"])]
    except (KeyError, ValueError):
        out["vara_loc"] = row.get("vara")
    out["tithi_loc"] = TITHI_L[lang][_TITHI_INDEX.get(row.get("tithi"), 0)]
    out["paksha_loc"] = PAKSHA_L[lang][0 if row.get("paksha") == "Shukla" else 1]
    if row.get("nakshatra") in NAKSHATRAS:
        out["nakshatra_loc"] = NAK_L[lang][NAKSHATRAS.index(row["nakshatra"])]
    if row.get("yoga") in YOGA_NAMES:
        out["yoga_loc"] = YOGA_L[lang][YOGA_NAMES.index(row["yoga"])]
    out["karana_loc"] = KARANA_L[lang].get(row.get("karana"), row.get("karana"))
    for key in ("masa_amanta", "masa_purnimanta"):
        name = _MASA_ALIAS.get(row.get(key), row.get(key))
        if name in MASA_EN:
            out[key + "_loc"] = MASA_L[lang][MASA_EN.index(name)]
        elif isinstance(name, str) and name.startswith("Adhika "):
            base = name.replace("Adhika ", "")
            out[key + "_loc"] = ("అధిక " if lang == "te" else "ಅಧಿಕ " if lang == "kn" else "अधिक " if lang == "mr" else "અધિક " if lang == "gu" else "অধিক ") + (MASA_L[lang][MASA_EN.index(base)] if base in MASA_EN else base)
    if row.get("moon_sign") in SIGNS:
        out["moon_sign_loc"] = SIGNS_L[lang][SIGNS.index(row["moon_sign"])]
    out["labels"] = LABELS[lang]
    out["lang"] = lang
    out["lang_name"] = LANGS[lang]
    return out


def sign_name(sign: int, lang: str) -> str:
    return SIGNS_L[lang][sign % 12] if lang in SIGNS_L else SIGNS[sign % 12]
